const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Define a polygon for southern Spain (roughly Andalusia region)
    const southernSpain = ee.Geometry.Polygon(
      [
        [-7.5, 35.8],
        [-7.5, 38.5],
        [-1.5, 38.5],
        [-1.5, 35.8],
        [-7.5, 35.8]
      ]);

    const startDate = '2023-04-01';
    const endDate = '2023-05-01'; // Exclusive

    // 2. Data Acquisition
    let era5Land = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
      .filterBounds(southernSpain)
      .filterDate(startDate, endDate)
      .select('2m_temperature'); // 2-meter air temperature in Kelvin

    // Check if the collection is empty
    const imageCount = await era5Land.size().getInfo();
    if (imageCount === 0) {
      console.log("No ERA5-Land images found for April 2023 in southern Spain.");
      console.log("C1");
      return;
    }
    console.log(`ERA5-Land images for April 2023: ${imageCount}`);

    // Function to convert Kelvin to Fahrenheit
    const kelvinToFahrenheit = (image) => {
      // Convert Kelvin to Celsius: K - 273.15
      // Convert Celsius to Fahrenheit: C * 9/5 + 32
      return image.subtract(273.15).multiply(9/5).add(32)
        .rename('temperature_F');
    };

    // Apply the conversion to all images in the collection
    const era5LandFahrenheit = era5Land.map(kelvinToFahrenheit);

    // 3. Processing: Get the maximum temperature over the entire period
    const maxTemperatureImage = era5LandFahrenheit.reduce(ee.Reducer.max());

    // Reduce the maximum temperature image to a single value over the region
    // Use a large scale appropriate for ERA5-Land (~10km resolution)
    const maxTempResult = await maxTemperatureImage.reduceRegion({
      reducer: ee.Reducer.max(),
      geometry: southernSpain,
      scale: 10000, // 10 km scale
      maxPixels: 1e9,
      crs: 'EPSG:4326' // Specify CRS to avoid projection issues
    }).get('temperature_F').getInfo();

    // 4. Validation & Final Answer
    if (maxTempResult === null || isNaN(maxTempResult)) {
      console.log("Calculation failed: Max temperature is None or NaN.");
      console.log("C3");
      return;
    }

    const thresholdFahrenheit = 90;
    const experiencedHighTemps = maxTempResult > thresholdFahrenheit;

    console.log(`Max temperature in Southern Spain (April 2023): ${maxTempResult.toFixed(2)} °F`);

    if (experiencedHighTemps) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred during the analysis:", error);
    // Attempt to catch common GEE errors or other exceptions
    if (error.message.includes("ImageCollection does not exist") ||
        error.message.includes("Band does not exist")) {
      console.log("D"); // Incorrect band or collection name
    } else if (error.message.includes("authentication") || error.message.includes("initialize")) {
      console.log("Authentication or initialization error. Check your Earth Engine setup.");
      console.log("D");
    } else {
      console.log("D"); // General calculation/runtime error
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
